body{margin:0;font:13px/1.4 system-ui,sans-serif;color:#1f2430;background:#f6f5f2}
.app{display:grid;height:100vh}
.side{background:#262a36;color:#cfd3dd;padding:16px 12px;display:flex;flex-direction:column;gap:6px}
.side b{color:#fff;font-size:14px;margin-bottom:10px}
.side span{padding:6px 10px;border-radius:8px}
.side span.on{background:#3b4152;color:#fff}
.top{background:#fff;border-bottom:1px solid #e3e1db;padding:10px 18px;display:flex;gap:18px;align-items:center}
.top b{margin-right:12px}
.top span.on{color:#5b4bdb;font-weight:600}
main{padding:18px;display:grid;gap:12px;align-content:start}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.card{background:#fff;border:1px solid #e3e1db;border-radius:12px;padding:12px}
.card small{color:#7a7f8c;display:block}
.card strong{font-size:20px}
.chart{background:#fff;border:1px solid #e3e1db;border-radius:12px;height:150px;padding:12px;display:flex;align-items:flex-end;gap:8px}
.chart i{flex:1;background:#8c80f0;border-radius:4px 4px 0 0;display:block}
.list{background:#fff;border:1px solid #e3e1db;border-radius:12px}
.list p{margin:0;padding:10px 12px;border-bottom:1px solid #eeece6}
.rail{display:grid;grid-template-columns:1fr 280px;gap:12px}
.side button,.top button{all:unset;padding:6px 10px;border-radius:8px;cursor:pointer;transition:background-color .18s ease,color .18s ease}
.side button:hover{background:#30354a;color:#fff}.side button.on{background:#3b4152;color:#fff}
.top button:hover{color:#1f2430;background:#f1efe9}.top button.on{color:#5b4bdb;font-weight:600}
.side button:focus-visible,.top button:focus-visible{box-shadow:0 0 0 2px #8c80f0}
.search{all:unset;background:#fff;border:1px solid #e3e1db;border-radius:10px;padding:8px 12px;transition:border-color .18s ease,box-shadow .18s ease}
.search:focus{border-color:#8c80f0;box-shadow:0 0 0 3px rgba(140,128,240,.2)}
.card{transition:transform .2s ease,box-shadow .2s ease}.card:hover{transform:translateY(-2px);box-shadow:0 6px 18px -10px rgba(31,36,48,.35)}
.chart i{transform-origin:bottom;animation:grow .7s cubic-bezier(.2,.8,.2,1) both;transition:background-color .18s ease}
.chart i:nth-child(2){animation-delay:.04s}.chart i:nth-child(3){animation-delay:.08s}.chart i:nth-child(4){animation-delay:.12s}.chart i:nth-child(5){animation-delay:.16s}.chart i:nth-child(6){animation-delay:.2s}.chart i:nth-child(7){animation-delay:.24s}.chart i:nth-child(8){animation-delay:.28s}
.chart i:hover{background:#5b4bdb}
@keyframes grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
.list p{transition:background-color .15s ease}.list p:hover{background:#faf9f6}

